-- Fonte: BCB ParticipantesSTR.csv (https://www.bcb.gov.br/content/estabilidadefinanceira/str1/ParticipantesSTR.csv).
CREATE TABLE IF NOT EXISTS app.instituicoes_bancarias (
    codigo_banco VARCHAR(3) PRIMARY KEY,
    nome_banco VARCHAR(150) NOT NULL,
    criado_em TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

